"""H4: the plain-language diff between policy versions, generated by code."""
import copy

from engine.policy import load_policy
from engine.policy_diff import diff
from engine.policy_explain import explain, inr, words

BASE = load_policy("5.0")


def changed(change):
    new = copy.deepcopy(BASE)
    change(new)
    return explain(BASE, new)


def test_no_change_gives_no_sentences():
    assert explain(BASE, copy.deepcopy(BASE)) == []


def test_a_limit_change_is_one_readable_sentence():
    sentences = changed(lambda p: p["parameters"]["limits"]["spot_po"].update(value=150000, operator="<="))
    assert sentences == ["Spot PO limit: below 2,00,000 becomes at or below 1,50,000"]


def test_a_window_change_reads_in_days():
    sentences = changed(lambda p: p["parameters"]["clubbing"]["creation_window"].update(length=10))
    assert sentences == ["Clubbing creation window: 14 calendar days becomes 10 calendar days"]


def test_a_new_plant_rule_says_where_it_goes_when_it_applies_and_what_it_does():
    def add(p):
        p["rules"].insert(4, {"id": "5.3A", "title": "Lubricants at Chakan", "clause_text": "...",
                              "when": {"and": [{"==": [{"var": "plant.plant"}, "CHK1"]},
                                               {"==": [{"var": "item.category"}, "Lubricants"]}]},
                              "then": {"decision": "SOURCING_REQUEST", "route": "RFQ", "supplier": "suggest",
                                       "price": "none", "suggest_count": 3}})
    assert changed(add) == ["New rule 5.3A 'Lubricants at Chakan' after 5.3: applies when plant is 'CHK1' and "
                            "item category is 'Lubricants'; outcome: RFQ with 3 suggested suppliers"]


def test_metadata_overrides_derived_facts_flags_and_removals_each_get_a_sentence():
    def many(p):
        p.update(version="5.1", effective_from="2026-12-01")
        p["overrides"].append({"id": "OV-1", "parameter": "limits.spot_po", "when": {"==": [{"var": "line.plant"}, "CHK1"]},
                               "set": {"value": 100000}})
        p["derived_facts"].append({"name": "lead_days", "expr": {"date_diff_days": [{"var": "first_line.need_by_date"},
                                                                                   {"var": "requirement.date"}]}})
        p["line_flags"] = [f for f in p["line_flags"] if f["id"] != "F6"]
        p["rules"] = [r for r in p["rules"] if r["id"] != "5.4"]
        p["parameters"]["valuation"]["include_non_active_suppliers"] = False
    sentences = changed(many)
    assert "Version: '5.0' becomes '5.1'" in sentences
    assert "Effective from: '2026-04-01' becomes '2026-12-01'" in sentences
    assert "New override OV-1: limits.spot_po gets value 1,00,000 when plant is 'CHK1'" in sentences
    assert "New derived fact lead_days = days from requirement date to need-by date" in sentences
    assert "Line flag F6 removed" in sentences and "Rule 5.4 removed" in sentences
    assert "Setting valuation.include_non_active_suppliers: true becomes false" in sentences


def test_every_changed_path_is_covered_by_some_sentence():
    def many(p):
        p["parameters"]["limits"]["rfq"]["value"] = 1500000
        p["parameters"]["ranking"]["preferred_score"]["weights"]["recency"] = 4
        p["parameters"]["matching"]["noise_phrases"].append("for fabrication")
        p["rules"][5]["then"]["suggest_count"] = 4
        p["line_checks"][0]["reason"] = "Quantity must be above zero"
    new = copy.deepcopy(BASE)
    many(new)
    sentences = explain(BASE, new)
    assert len(diff(BASE, new)) == 5 and len(sentences) == 5
    assert "RFQ limit: below 10,00,000 becomes below 15,00,000" in sentences
    assert any(s.startswith("Rule 5.5 'RFQ' changed (then)") for s in sentences)


def test_a_reworded_rule_says_only_the_wording_changed():
    sentences = changed(lambda p: p["rules"][4].update(clause_text="Spot PO, reworded."))
    assert sentences == ["Rule 5.4 'Spot PO': wording updated to 'Spot PO, reworded.' (condition and outcome unchanged)"]


def test_an_unrecognised_change_falls_back_to_path_old_and_new():
    new = copy.deepcopy(BASE)
    new["translation_notes"] = ["checked"]
    new["schema_version"] = "2"
    assert explain(BASE, new) == ["schema_version: '1' becomes '2'", 'translation_notes: nothing becomes ["checked"]']


def test_expressions_read_as_words():
    assert words({"!": {"meets_limit": [{"var": "requirement.value_inr"}, "limits.rfq"]}}, BASE["parameters"]) == \
        "not (requirement value is below 10,00,000 (RFQ limit))"
    assert words({">": [{"*": [100, {"-": [{"var": "requirement.valuation_price"}, {"var": "item.standard_price"}]}]}, 15]}) == \
        "100 * (valuation price - standard price) is above 15"
    assert words({"some": [{"var": "lines"}, {"==": [{"var": "urgency"}, "Emergency"]}]}) == "any line has urgency is 'Emergency'"


def test_indian_digit_grouping():
    assert [inr(x) for x in (999, 1000, 150000, 1500000, 60036704.08)] == ["999", "1,000", "1,50,000", "15,00,000", "6,00,36,704.08"]
